INSERT INTO `products` (`p_id`, `p_name`, `main_category_id`, `p_category_id`, `p_short_description`, `p_long_description`, `p_price`, `p_old_price`, `p_visibility_status`, `p_stock`, `p_type`, `created_at`, `updated_at`) VALUES
(5, 'Classy formal pants', 1, 5, 'Formal pants, also known as dress pants or trousers, are characterized by their tailored construction, clean lines, and professional appearance. They are designed for formal or semi-formal occasions, such as business meetings, corporate events, and formal dinners.', '<ul class=\"KsbFXc U6u95\" jscontroller=\"mPWODf\" jsuid=\"Ebh3c_p\" data-processed=\"true\" style=\"margin: 10px 0px 20px; padding: 0px; font-family: &quot;Google Sans&quot;, Roboto, Arial, sans-serif; font-size: 16px; line-height: 24px; padding-inline-start: 16px; color: rgb(10, 10, 10);\"><li jscontroller=\"vsuOFb\" jsuid=\"Ebh3c_w\" data-hveid=\"CAMQAg\" data-processed=\"true\" style=\"margin: 0px 0px 12px; padding: 0px; list-style: disc; padding-inline-start: 4px;\"><span class=\"T286Pc\" data-sfc-cp=\"\" jscontroller=\"fly6D\" jsuid=\"Ebh3c_x\" data-processed=\"true\" style=\"overflow-wrap: break-word;\"><span class=\"Yjhzub\" jscontroller=\"VhkxAe\" jsuid=\"Ebh3c_y\" data-processed=\"true\" style=\"font-weight: bolder;\">Design Details:</span></span><ul class=\"KsbFXc U6u95\" jscontroller=\"mPWODf\" jsuid=\"Ebh3c_z\" data-processed=\"true\" style=\"margin: 10px 0px 20px; padding: 0px; line-height: 24px; padding-inline-start: 16px;\"><li jscontroller=\"vsuOFb\" jsuid=\"Ebh3c_10\" data-hveid=\"CAMQAw\" data-processed=\"true\" style=\"margin: 0px 0px 12px; padding: 0px; list-style: circle; padding-inline-start: 0px;\"><span class=\"T286Pc\" data-sfc-cp=\"\" jscontroller=\"fly6D\" jsuid=\"Ebh3c_11\" data-processed=\"true\" style=\"overflow-wrap: break-word;\"><span class=\"Yjhzub\" jscontroller=\"VhkxAe\" jsuid=\"Ebh3c_12\" data-processed=\"true\" style=\"font-weight: bolder;\">Flat Front or Pleats:</span>&nbsp;They can be flat-front for a contemporary, smooth appearance or feature single/double pleats, which are folds of fabric at the waistband that add a traditional, fuller look.</span></li><li jscontroller=\"vsuOFb\" jsuid=\"Ebh3c_13\" data-hveid=\"CAMQBA\" data-processed=\"true\" style=\"margin: 0px 0px 12px; padding: 0px; list-style: circle; padding-inline-start: 0px;\"><span class=\"T286Pc\" data-sfc-cp=\"\" jscontroller=\"fly6D\" jsuid=\"Ebh3c_14\" data-processed=\"true\" style=\"overflow-wrap: break-word;\"><span class=\"Yjhzub\" jscontroller=\"VhkxAe\" jsuid=\"Ebh3c_15\" data-processed=\"true\" style=\"font-weight: bolder;\">Creases:</span>&nbsp;A defining feature is the sharp, pressed crease running down the front and back of each leg, which enhances their neat and formal appearance.</span></li><li jscontroller=\"vsuOFb\" jsuid=\"Ebh3c_16\" data-hveid=\"CAMQBQ\" data-processed=\"true\" style=\"margin: 0px 0px 12px; padding: 0px; list-style: circle; padding-inline-start: 0px;\"><span class=\"T286Pc\" data-sfc-cp=\"\" jscontroller=\"fly6D\" jsuid=\"Ebh3c_17\" data-processed=\"true\" style=\"overflow-wrap: break-word;\"><span class=\"Yjhzub\" jscontroller=\"VhkxAe\" jsuid=\"Ebh3c_18\" data-processed=\"true\" style=\"font-weight: bolder;\">Waistband and Fly:</span>&nbsp;They typically have a smooth waistband with belt loops, a a zip fly, and a hook-and-bar or button closure for security and a clean finish.</span></li><li jscontroller=\"vsuOFb\" jsuid=\"Ebh3c_19\" data-hveid=\"CAMQBg\" data-processed=\"true\" style=\"margin: 0px 0px 12px; padding: 0px; list-style: circle; padding-inline-start: 0px;\"><span class=\"T286Pc\" data-sfc-cp=\"\" jscontroller=\"fly6D\" jsuid=\"Ebh3c_1a\" data-processed=\"true\" style=\"overflow-wrap: break-word;\"><span class=\"Yjhzub\" jscontroller=\"VhkxAe\" jsuid=\"Ebh3c_1b\" data-processed=\"true\" style=\"font-weight: bolder;\">Pockets:</span>&nbsp;Front pockets are usually slant or vertical to maintain the sleek silhouette, while back pockets are often welted, sometimes with buttons.</span></li></ul></li><li jscontroller=\"vsuOFb\" jsuid=\"Ebh3c_1c\" data-hveid=\"CAMQBw\" data-processed=\"true\" style=\"margin: 0px 0px 12px; padding: 0px; list-style: disc; padding-inline-start: 4px;\"><span class=\"T286Pc\" data-sfc-cp=\"\" jscontroller=\"fly6D\" jsuid=\"Ebh3c_1d\" data-processed=\"true\" style=\"overflow-wrap: break-word;\"><span class=\"Yjhzub\" jscontroller=\"VhkxAe\" jsuid=\"Ebh3c_1e\" data-processed=\"true\" style=\"font-weight: bolder;\">Hem:</span>&nbsp;For a proper, tailored look, the hem is typically plain (without cuffs or \"turn-ups\"), ensuring they fit correctly over formal footwear.</span><span jsuid=\"Ebh3c_1f\" class=\"uJ19be notranslate\" jsaction=\"rcuQ6b:&amp;Ebh3c_1f|npT2md\" jscontroller=\"udAs2b\" data-wiz-uids=\"Ebh3c_1f,Ebh3c_1g,Ebh3c_1h\" data-processed=\"true\"><span class=\"vKEkVd\" data-animation-atomic=\"\" data-processed=\"true\" style=\"text-wrap-mode: nowrap; position: relative;\">&nbsp;<button jsuid=\"Ebh3c_1h\" tabindex=\"0\" data-amic=\"true\" data-icl-uuid=\"107693e2-e62d-42d0-a916-b76eb9c50b0d\" aria-label=\"View related links\" class=\"rBl3me\" jsaction=\"click:&amp;Ebh3c_1f|S9kKve;mouseenter:&amp;Ebh3c_1f|sbHm2b;mouseleave:&amp;Ebh3c_1f|Tx5Rb\" data-wiz-attrbind=\"disabled=Ebh3c_1f_C5gNJc;class=Ebh3c_1f_UpSNec;\" data-ved=\"2ahUKEwj1vP-Xp5yRAxVMS3ADHf_zKJwQye0OegQIAxAI\" data-processed=\"true\" style=\"margin-right: 6px; background: none 0% 0% / auto repeat scroll padding-box border-box rgb(229, 237, 255); border-width: initial; border-style: none; border-radius: 10px; height: 20px; padding: 0px; width: 28px; position: relative; outline: 0px;\"><span class=\"wiMplc ofC0Ud\" data-processed=\"true\" style=\"color: rgb(0, 29, 53); display: inline-block; transform: rotate(135deg);\"><svg style=\"margin-top: 3px;\" fill=\"currentColor\" width=\"12px\" height=\"12px\" focusable=\"false\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path d=\"M3.9 12c0-1.71 1.39-3.1 3.1-3.1h4V7H7c-2.76 0-5 2.24-5 5s2.24 5 5 5h4v-1.9H7c-1.71 0-3.1-1.39-3.1-3.1zM8 13h8v-2H8v2zm9-6h-4v1.9h4c1.71 0 3.1 1.39 3.1 3.1s-1.39 3.1-3.1 3.1h-4V17h4c2.76 0 5-2.24 5-5s-2.24-5-5-5z\"></path></svg></span></button></span></span></li></ul><